import { companionCombatProfile } from './companion-combat-profile.js';
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

/** Render one native disclosure. Opening it is only a view, never an action. */
export function renderCompanionCombatProfile(game, companion, { readinessReason = null } = {}) {
  const p = companionCombatProfile(game, companion), a = p.actor, g = p.growth;
  const growth = !g.enabled ? 'This older life uses combat rules without victory-based growth.' : g.nextAt === null ? `Growth ${g.step}/${g.max} · ${g.victories} shared victories. The existing combat-growth cap is reached.` : `Growth ${g.step}/${g.max} · ${g.victories} shared victories. Next step at ${g.nextAt} victories (${g.remaining} more).`;
  const move = m => `<p class="small-copy" data-companion-move="${escape(m.id)}"><strong>${escape(m.label)} · ${m.cost ? `${m.cost} MP` : 'Free'} · ${escape(m.kind)}</strong><br>${escape(m.description)}${m.cost > a.mp ? ' <span class="disabled-reason">Not enough current Focus.</span>' : ''}</p>`;
  return `<p class="small-copy companion-readiness" data-companion-readiness="${escape(p.readiness.code)}">${escape(p.readiness.detail)}${readinessReason ? ` <span class="disabled-reason">${escape(readinessReason)}</span>` : ''}</p><details class="companion-combat-profile" data-companion-profile="${escape(companion.id)}" data-disclosure="companion-combat-${escape(companion.id)}"><summary>Combat · ${escape(p.calling)}${g.enabled ? ` · growth ${g.step}/${g.max}` : ''}</summary><p class="small-copy"><strong>Role ${escape(p.role)} · Calling ${escape(p.calling)}</strong><br>Health ${a.hp}/${a.maxHp} · Focus ${a.mp}/${a.maxMp}<br>Attack ${p.attack} · Armor ${p.armor} · Initiative ${p.initiative} · Spell power ${p.spellPower}</p><p class="small-copy">Entry values before temporary battle effects and enemy replies; target armor, wards and resistance affect final damage. Initiative is the actual battle-order speed.</p>${p.legacyDefaults ? '<p class="small-copy">Missing legacy reserves use battle defaults for this readout only. Viewing changes no recorded resources.</p>' : ''}<p class="small-copy" data-companion-growth>${escape(growth)}${g.enabled ? ' Victories count only when this companion participated. Growth improves attack, spell attributes and periodic armor, not maximum Health, Focus or initiative.' : ''}</p><h4>Battle moves</h4>${p.moves.map(move).join('')}<h4>Chapter-earned techniques</h4>${p.techniques.length ? p.techniques.map(move).join('') : '<p class="small-copy">None learned yet. Their own recorded chapter choices can earn techniques; viewing this profile grants none.</p>'}<p class="small-copy">Shared supplies, retreat and any earned party formation remain battle commands.</p></details>`;
}
